export class DemoDataService {
  static isDemoMode(): boolean {
    return true;
  }

  static getRepositories(): DemoRepository[] {
    return DEMO_REPOSITORIES;
  }

  static getRepositoryById(id: string): DemoRepository | null {
    return DEMO_REPOSITORIES.find((r) => r.id === id || r._id === id) || null;
  }

  static getAnalysisById(id: string): DemoAnalysis | null {
    // If id matches a known repo or analysis id, return corresponding analysis
    if (DEMO_ANALYSES[id]) return DEMO_ANALYSES[id];
    const found = Object.values(DEMO_ANALYSES).find(
      (a) => a.id === id || a._id === id || a.repositoryId === id
    );
    return found || null;
  }

  static getHotspots(analysisId?: string): HotspotItem[] {
    return DEMO_HOTSPOTS;
  }

  static getFileMetrics(analysisId?: string): DemoFileMetric[] {
    return DEMO_FILE_METRICS;
  }

  static getTrends(repositoryId?: string): DemoTrendPoint[] {
    return DEMO_TRENDS;
  }

  static getRecommendations(analysisId?: string): ActionableRecommendation[] {
    return DEMO_RECOMMENDATIONS;
  }

  static getFinancialCost(analysisId?: string, hourlyRate: number = 95): FinancialValuation {
    const analysis = this.getAnalysisById(analysisId || 'analysis-demo-fintech-01');
    const summary = analysis?.summary || DEMO_ANALYSES['repo-demo-fintech-01'].summary;
    const rate = hourlyRate > 0 ? hourlyRate : 95;

    const totalHours = summary.totalDebtHours;
    const remediationCost = Math.round(totalHours * rate);
    const historicalCost = summary.historicalReworkCost;
    const avoidableCost = summary.annualAvoidableCost;
    const netBenefit = summary.potentialRefactoringBenefit;
    const roi = Number(((avoidableCost * 2) / remediationCost).toFixed(2));
    const paybackMonths = Number((remediationCost / (avoidableCost / 12)).toFixed(1));

    return {
      currency: 'USD',
      hourlyRate: rate,
      estimatedRemediationInvestment: {
        totalHours,
        totalCost: remediationCost,
        trace: {
          input: {
            totalRemediationHours: totalHours,
            engineeringHourlyRate: rate,
            hotspotsIdentified: summary.hotspotCount,
          },
          formula: 'RemediationCost = totalRemediationHours * engineeringHourlyRate',
          result: remediationCost,
          explanation:
            'Direct capital cost required to refactor 14 identified hotspot modules down to maintainable thresholds.',
        },
      },
      historicalMaintenanceReworkBurden: {
        totalHours: Math.round(historicalCost / rate),
        totalCost: historicalCost,
        trace: {
          input: {
            estimatedReworkHours: Math.round(historicalCost / rate),
            engineeringHourlyRate: rate,
            historicalDefects: 31,
          },
          formula: 'HistoricalBurden = historicalReworkHours * engineeringHourlyRate',
          result: historicalCost,
          explanation:
            'Engineering capital expended over the past 12 months on preventable bug triage, regression patches, and high-friction code modifications.',
        },
      },
      estimatedFutureAvoidableCost: {
        projectedAnnualCost: avoidableCost,
        trace: {
          input: {
            criticalHotspots: summary.criticalHotspots,
            annualHoursLostPerHotspot: 180,
            engineeringHourlyRate: rate,
          },
          formula: 'AvoidableAnnualCost = criticalHotspots * annualHoursLostPerHotspot * engineeringHourlyRate',
          result: avoidableCost,
          explanation:
            'Projected future drag in delayed sprint velocity and avoidable maintenance overhead over the next 12 months if technical debt is not addressed.',
        },
      },
      potentialRefactoringBenefit: {
        netSavings: netBenefit,
        roiRatio: roi,
        paybackMonths,
        trace: {
          input: {
            twoYearAvoidedCost: avoidableCost * 2,
            totalRemediationCost: remediationCost,
          },
          formula: 'NetSavings = (AvoidableAnnualCost * 2) - RemediationCost; ROI = (AvoidableAnnualCost * 2) / RemediationCost',
          result: netBenefit,
          explanation:
            'Projected net savings and return on investment over a 24-month horizon following targeted remediation of critical hotspots.',
        },
      },
      disclaimer:
        'Model-based financial estimates are predictive indicators based on engineering economics heuristics and historical repository metrics, not exact balance sheet accounting losses.',
    };
  }
}
